//! The door's guarantee, held against korg's **real** tool catalogue
//! (`crates/korg-mcp/tests/tools_schema.json`, regenerated by `just gen`), so it
//! drifts with korg's tool surface rather than a hand-typed list — and, for the
//! klams door, against klams's catalogue as committed at `tests/klams_tools.json`.
//!
//! The korg door's ruling is total (sprint 095): every korg tool is a read, a
//! ruled write, or refused by name, and a tool korg adds fails here until
//! somebody says which.

mod common;

use common::*;
use korg_gate::allowlist::{
    looks_read_only, DUET_ORIGIN, KLAMS_READ_TOOLS, KLAMS_REFUSED_TOOLS, READ_TOOLS, REFUSED_TOOLS,
    WRITE_TOOLS,
};
use serde_json::json;

fn korg_rulings() -> impl Iterator<Item = &'static &'static str> {
    READ_TOOLS.iter().chain(WRITE_TOOLS).chain(REFUSED_TOOLS)
}

#[test]
fn every_ruled_tool_exists_in_the_catalogue() {
    let catalogue = catalogue();
    for name in korg_rulings() {
        assert!(
            catalogue.iter().any(|c| c == name),
            "the korg rulings name `{name}`, which korg no longer serves — drop it"
        );
    }
}

#[test]
fn every_korg_tool_has_been_ruled_on() {
    // A new korg tool fails here until somebody decides whether it may reach
    // the public internet: READ_TOOLS, WRITE_TOOLS (a decision, korg+ GP-17)
    // or REFUSED_TOOLS.
    let unruled: Vec<_> = catalogue()
        .into_iter()
        .filter(|n| !korg_rulings().any(|r| r == n))
        .collect();
    assert!(
        unruled.is_empty(),
        "korg serves tools korg-gate has not ruled on: {unruled:?} \
         (crates/korg-gate/src/allowlist.rs)"
    );
}

#[test]
fn every_read_shaped_tool_in_the_catalogue_is_a_read() {
    // If a `get_`/`list_` tool is not a pure read, the naming is the bug.
    let misfiled: Vec<_> = catalogue()
        .into_iter()
        .filter(|n| looks_read_only(n) && !READ_TOOLS.contains(&n.as_str()))
        .collect();
    assert!(
        misfiled.is_empty(),
        "read-shaped but not in READ_TOOLS: {misfiled:?}"
    );
}

#[test]
fn the_write_set_is_exactly_the_ruled_eight() {
    assert_eq!(
        WRITE_TOOLS,
        [
            "add_comment",
            "create_link",
            "create_program",
            "create_work_item",
            "propose_sprint",
            "relate",
            "set_awaiting",
            "update_work_item"
        ],
        "widening the korg door's writes is a decision (korg+ GP-17), not an edit"
    );
}

#[tokio::test]
async fn every_refused_tool_is_refused_on_call_and_the_list_is_reads_plus_writes() {
    let h = Harness::start().await;
    let (_, token, _) = h.access_token().await;

    assert!(
        REFUSED_TOOLS.len() > 20,
        "the catalogue lost its refused writes? {REFUSED_TOOLS:?}"
    );
    for (i, name) in REFUSED_TOOLS.iter().enumerate() {
        let resp = h
            .rpc(
                &token,
                json!({"jsonrpc":"2.0","id":i,"method":"tools/call",
                       "params":{"name":name,"arguments":{}}}),
            )
            .await;
        assert_eq!(
            resp.status(),
            200,
            "{name}: a refusal is a JSON-RPC error, not an HTTP one"
        );
        let body = resp.json_value().await;
        assert_eq!(body["id"], i, "{name}");
        assert!(
            body["error"]["code"].is_i64(),
            "{name} was not refused: {body}"
        );
        assert!(body.get("result").is_none(), "{name}");
    }
    assert!(
        h.seen
            .0
            .lock()
            .unwrap()
            .iter()
            .all(|(_, m)| m["method"] != "tools/call"),
        "a refused tools/call reached korg"
    );

    let listed = h
        .rpc(
            &token,
            json!({"jsonrpc":"2.0","id":"l","method":"tools/list"}),
        )
        .await
        .json_value()
        .await;
    let mut names: Vec<&str> = listed["result"]["tools"]
        .as_array()
        .unwrap()
        .iter()
        .map(|t| t["name"].as_str().unwrap())
        .collect();
    for name in REFUSED_TOOLS {
        assert!(!names.contains(name), "{name} is listed");
    }
    let mut expected: Vec<&str> = READ_TOOLS.iter().chain(WRITE_TOOLS).copied().collect();
    expected.sort_unstable();
    names.sort_unstable();
    assert_eq!(names, expected);
    assert_eq!(names.len(), 34);
}

#[tokio::test]
async fn every_write_tool_reaches_korg_stamped_as_duet() {
    let h = Harness::start().await;
    let (_, token, _) = h.access_token().await;

    for (i, name) in WRITE_TOOLS.iter().enumerate() {
        let body = h
            .rpc(
                &token,
                json!({"jsonrpc":"2.0","id":i,"method":"tools/call",
                       "params":{"name":name,"arguments":{"title":"t","origin":"overseer"}}}),
            )
            .await
            .json_value()
            .await;
        assert_eq!(
            body["result"]["content"][0]["text"],
            format!("called {name}"),
            "{name}: {body}"
        );
    }
    let seen = h.seen.0.lock().unwrap();
    let calls: Vec<_> = seen
        .iter()
        .filter(|(_, m)| m["method"] == "tools/call")
        .collect();
    assert_eq!(calls.len(), WRITE_TOOLS.len());
    for (headers, msg) in calls {
        let name = msg["params"]["name"].as_str().unwrap();
        assert_eq!(headers["x-homelab-agent"], "claude-duet", "{name}");
        // Everything but origin passes as sent.
        assert_eq!(msg["params"]["arguments"]["title"], "t", "{name}");
        let origin = &msg["params"]["arguments"]["origin"];
        match name {
            // The two tools with korg's `origin` field: overwritten.
            "add_comment" | "relate" => assert_eq!(origin, DUET_ORIGIN, "{name}"),
            // Anything else is not the gate's field to touch.
            _ => assert_eq!(origin, "overseer", "{name}"),
        }
    }
}

#[tokio::test]
async fn origin_is_stamped_when_the_caller_sends_none_and_refused_on_non_object_arguments() {
    let h = Harness::start().await;
    let (_, token, _) = h.access_token().await;

    for (i, arguments) in [json!({"node_id": 1, "body": "b"}), json!(null)]
        .into_iter()
        .enumerate()
    {
        h.rpc(
            &token,
            json!({"jsonrpc":"2.0","id":i,"method":"tools/call",
                   "params":{"name":"add_comment","arguments":arguments}}),
        )
        .await;
    }
    // No `arguments` key at all.
    h.rpc(
        &token,
        json!({"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":"relate"}}),
    )
    .await;
    {
        let seen = h.seen.0.lock().unwrap();
        let origins: Vec<_> = seen
            .iter()
            .map(|(_, m)| m["params"]["arguments"]["origin"].clone())
            .collect();
        assert_eq!(origins, [DUET_ORIGIN, DUET_ORIGIN, DUET_ORIGIN]);
        assert_eq!(seen[0].1["params"]["arguments"]["body"], "b");
    }

    let body = h
        .rpc(
            &token,
            json!({"jsonrpc":"2.0","id":9,"method":"tools/call",
                   "params":{"name":"add_comment","arguments":"origin=overseer"}}),
        )
        .await
        .json_value()
        .await;
    assert_eq!(body["error"]["code"], -32602, "{body}");
    assert_eq!(
        h.seen.0.lock().unwrap().len(),
        3,
        "an unstampable call reached korg"
    );
}

#[tokio::test]
async fn non_lifecycle_methods_batches_and_responses_are_refused() {
    let h = Harness::start().await;
    let (_, token, _) = h.access_token().await;

    for method in [
        "resources/list",
        "resources/read",
        "prompts/list",
        "completion/complete",
        "logging/setLevel",
    ] {
        let body = h
            .rpc(&token, json!({"jsonrpc":"2.0","id":1,"method":method}))
            .await
            .json_value()
            .await;
        assert_eq!(body["error"]["code"], -32601, "{method}");
    }

    // A refused notification has no id to answer: HTTP 400.
    let resp = h
        .rpc(
            &token,
            json!({"jsonrpc":"2.0","method":"notifications/roots/list_changed"}),
        )
        .await;
    assert_eq!(resp.status(), 400);

    // A batch is refused whole, even one that hides a write behind a read.
    let resp = h
        .rpc(
            &token,
            json!([{"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"get_item"}},
                   {"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":"delete_area"}}]),
        )
        .await;
    assert_eq!(resp.status(), 400);

    assert!(
        h.seen.0.lock().unwrap().is_empty(),
        "a refused message reached korg"
    );

    // The lifecycle still passes.
    let resp = h
        .rpc(
            &token,
            json!({"jsonrpc":"2.0","id":1,"method":"initialize","params":{}}),
        )
        .await;
    assert_eq!(resp.status(), 200);
    let resp = h
        .rpc(
            &token,
            json!({"jsonrpc":"2.0","method":"notifications/initialized"}),
        )
        .await;
    assert_eq!(resp.status(), 202);
}

#[tokio::test]
async fn duplicate_keys_cannot_smuggle_a_write_past_the_check() {
    let h = Harness::start().await;
    let (_, token, _) = h.access_token().await;
    // serde keeps the last duplicate; whatever the gate checked is what it
    // forwards, because it forwards its own re-serialisation.
    let raw = r#"{"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"delete_area","name":"get_item"}}"#;
    let resp = h
        .http
        .post(h.url("/mcp"))
        .bearer_auth(&token)
        .header("content-type", "application/json")
        .body(raw)
        .send()
        .await
        .unwrap();
    assert_eq!(resp.status(), 200);
    let seen = h.seen.0.lock().unwrap();
    let (_, forwarded) = seen.last().unwrap();
    assert_eq!(forwarded["params"]["name"], "get_item");
}

// ---- The klams door (sprint 094, WI 4293) ----

#[test]
fn every_klams_tool_has_been_ruled_on_and_every_ruling_names_a_real_tool() {
    // klams has no read naming rule to lean on, so the ruling is total: a tool
    // klams adds fails here until it is put in KLAMS_READ_TOOLS (published to
    // the internet) or KLAMS_REFUSED_TOOLS.
    let catalogue = klams_catalogue();
    let unruled: Vec<_> = catalogue
        .iter()
        .filter(|n| {
            !KLAMS_READ_TOOLS.contains(&n.as_str()) && !KLAMS_REFUSED_TOOLS.contains(&n.as_str())
        })
        .collect();
    assert!(
        unruled.is_empty(),
        "klams serves tools korg-gate has not ruled on: {unruled:?} \
         (crates/korg-gate/src/allowlist.rs)"
    );
    for name in KLAMS_READ_TOOLS.iter().chain(KLAMS_REFUSED_TOOLS) {
        assert!(
            catalogue.iter().any(|c| c == name),
            "the klams rulings name `{name}`, which klams no longer serves — drop it"
        );
    }
    assert_eq!(
        KLAMS_READ_TOOLS,
        [
            "event_search",
            "memory_get",
            "memory_related",
            "memory_search"
        ],
        "widening the klams door is a decision (korg+ GP-17), not an edit"
    );
}

#[tokio::test]
async fn every_klams_write_is_refused_on_call_and_the_list_is_exactly_the_four_reads() {
    let h = Harness::start().await;
    let (_, token, _) = h.klams_token().await;

    // Every klams tool outside the four, plus a korg read: the klams door
    // knows only its own list.
    let refused: Vec<String> = klams_catalogue()
        .into_iter()
        .filter(|n| !KLAMS_READ_TOOLS.contains(&n.as_str()))
        .chain(["get_item".to_string(), "search".to_string()])
        .collect();
    assert_eq!(refused.len(), 9);
    for (i, name) in refused.iter().enumerate() {
        let body = h
            .rpc_at(
                "/klams/mcp",
                &token,
                json!({"jsonrpc":"2.0","id":i,"method":"tools/call",
                       "params":{"name":name,"arguments":{}}}),
            )
            .await
            .json_value()
            .await;
        assert_eq!(body["id"], i, "{name}");
        assert_eq!(
            body["error"]["code"], -32602,
            "{name} was not refused: {body}"
        );
        assert!(
            body["error"]["message"]
                .as_str()
                .unwrap()
                .contains("exposes klams read-only"),
            "{body}"
        );
    }
    assert!(
        h.klams_seen
            .0
            .lock()
            .unwrap()
            .iter()
            .all(|(_, m)| m["method"] != "tools/call"),
        "a refused tools/call reached klams"
    );

    // tools/list, through klams's SSE answer and its priming event.
    let text = h
        .rpc_at(
            "/klams/mcp",
            &token,
            json!({"jsonrpc":"2.0","id":"l","method":"tools/list"}),
        )
        .await
        .text()
        .await
        .unwrap();
    let answer = text
        .split("\n\n")
        .filter_map(|ev| ev.lines().find_map(|l| l.strip_prefix("data: ")))
        .find(|d| !d.trim().is_empty())
        .unwrap_or_else(|| panic!("no answer in {text:?}"));
    let listed: serde_json::Value = serde_json::from_str(answer).unwrap();
    let mut names: Vec<&str> = listed["result"]["tools"]
        .as_array()
        .unwrap()
        .iter()
        .map(|t| t["name"].as_str().unwrap())
        .collect();
    names.sort_unstable();
    assert_eq!(names, KLAMS_READ_TOOLS);
}

#[tokio::test]
async fn a_klams_read_is_refused_at_the_korg_door() {
    let h = Harness::start().await;
    let (_, token, _) = h.access_token().await;
    let body = h
        .rpc(
            &token,
            json!({"jsonrpc":"2.0","id":1,"method":"tools/call",
                   "params":{"name":"memory_search","arguments":{}}}),
        )
        .await
        .json_value()
        .await;
    assert_eq!(body["error"]["code"], -32602);
    assert!(body["error"]["message"]
        .as_str()
        .unwrap()
        .contains("exposes korg's reads and the ruled write set"));
}
